size_t bcachefs_tiering_db_size(void) {
    return sizeof(g_db) / sizeof(g_db[0]);
}

void bcachefs_tiering_init(void) {
    g_online = true;
    kprintf("[FS/TIERING] NVMe <-> SSD <-> HDD Extent Tiering + Writeback Cache + CopyGC (%lu rules)\n", (unsigned long)bcachefs_tiering_db_size());
}

bool bcachefs_tiering_selftest(void) {
    return g_online && bcachefs_tiering_db_size() >= 3400;
}
